<?php
declare(strict_types=1); defined('ABSPATH') || exit;
trait SN_Future_Superset_Core {
    public static function cleanup(): void {global $wpdb;$now=self::now();$due=$wpdb->get_results($wpdb->prepare("SELECT * FROM ".self::records_table()." WHERE feature_id='F17-FUT-07' AND state='active' AND expires_at<=%s ORDER BY id ASC LIMIT 200",$now));foreach(is_array($due)?$due:[] as $x){$d=self::decode($x);if(is_wp_error($d))continue;do_action('sn_network_notification_requested',['owner'=>'file-17','recipient_id'=>(int)$x->owner_id,'type'=>'communication_reminder','title'=>'Communication reminder','body'=>mb_substr(sanitize_text_field((string)($d['label']??'Reminder')),0,191),'entity_type'=>'conversation','entity_id'=>(int)$x->scope_id,'message_id'=>(int)($d['message_id']??0)]);$wpdb->update(self::records_table(),['state'=>'fired','updated_at'=>$now,'version'=>(int)$x->version+1],['id'=>(int)$x->id,'state'=>'active','version'=>(int)$x->version]);}$temp=$wpdb->get_results($wpdb->prepare("SELECT * FROM ".self::records_table()." WHERE feature_id='F17-FUT-13' AND state='active' AND expires_at<=%s ORDER BY id ASC LIMIT 200",$now));foreach(is_array($temp)?$temp:[] as $x)self::expire_temp($x);$wpdb->query($wpdb->prepare("UPDATE ".self::records_table()." SET state='expired',updated_at=%s,version=version+1 WHERE state='active' AND expires_at IS NOT NULL AND expires_at<%s AND feature_id NOT IN ('F17-FUT-07','F17-FUT-13')",$now,$now));}
    public static function register_exporter(array $e): array {$e['sabri-network-future']=['exporter_friendly_name'=>'Sabri Network Advanced Communication','callback'=>[self::class,'privacy_export']];return $e;} public static function register_eraser(array $e): array {$e['sabri-network-future']=['eraser_friendly_name'=>'Sabri Network Advanced Communication','callback'=>[self::class,'privacy_erase']];return $e;}
    public static function privacy_export(string $email,int $page=1): array {global $wpdb;$u=get_user_by('email',$email);if(!$u)return ['data'=>[],'done'=>true];$rows=$wpdb->get_results($wpdb->prepare('SELECT * FROM '.self::records_table().' WHERE owner_id=%d ORDER BY id ASC LIMIT 100 OFFSET %d',(int)$u->ID,max(0,$page-1)*100));$data=[];foreach(is_array($rows)?$rows:[] as $x){$d=self::decode($x);$data[]=['group_id'=>'sabri-network-future','group_label'=>'Advanced Communication','item_id'=>'future-record-'.(int)$x->id,'data'=>[['name'=>'Feature','value'=>(string)$x->feature_id],['name'=>'Scope','value'=>(string)$x->scope_type.':'.(int)$x->scope_id],['name'=>'State','value'=>(string)$x->state],['name'=>'Data','value'=>is_wp_error($d)?'[encrypted data unavailable]':wp_json_encode($d)]]];}return ['data'=>$data,'done'=>count($rows)<100];}
    public static function privacy_erase(string $email,int $page=1): array {global $wpdb;$u=get_user_by('email',$email);if(!$u)return ['items_removed'=>false,'items_retained'=>false,'messages'=>[],'done'=>true];$rows=$wpdb->get_results($wpdb->prepare("SELECT * FROM ".self::records_table()." WHERE owner_id=%d AND state NOT IN ('deleted','erased') ORDER BY id ASC LIMIT 100",(int)$u->ID));$removed=0;$retained=0;foreach(is_array($rows)?$rows:[] as $x){if($x->feature_id==='F17-FUT-03'){$retained++;continue;}$wpdb->update(self::records_table(),['payload_cipher'=>null,'state'=>'erased','updated_at'=>self::now()],['id'=>(int)$x->id]);$removed++;}$versions=$wpdb->get_results($wpdb->prepare('SELECT v.id,v.message_id FROM '.self::versions_table().' v INNER JOIN '.SN_DB::table('messages').' m ON m.id=v.message_id WHERE m.sender_id=%d LIMIT 200',(int)$u->ID));foreach(is_array($versions)?$versions:[] as $v){if((bool)apply_filters('sn_network_message_version_hold',false,(int)$v->message_id,(int)$u->ID)){$retained++;continue;}$wpdb->delete(self::versions_table(),['id'=>(int)$v->id],['%d']);$removed++;}return ['items_removed'=>$removed>0,'items_retained'=>$retained>0,'messages'=>$retained?['Integrity records under an active hold were retained.']:[],'done'=>count($rows)<100&&count($versions)<200];}
    public static function register_assets(): void {wp_register_style('sn-future-superset',SN_URL.'assets/css/future-superset.css',[],SN_VERSION);wp_register_script('sn-future-superset',SN_URL.'assets/js/future-superset.js',[],SN_VERSION,true);}
    public static function render_workspace(): string {if(!is_user_logged_in())return '<div class="snf-card"><p>Sign in to use advanced communication controls.</p></div>';wp_enqueue_style('sn-future-superset');wp_enqueue_script('sn-future-superset');wp_localize_script('sn-future-superset','SN_FUTURE_CONFIG',['restUrl'=>esc_url_raw(rest_url('sabri-network/v2/')),'nonce'=>wp_create_nonce('wp_rest')]);return '<section id="sn-future-workspace" class="snf-workspace" aria-labelledby="snf-title"><header><h2 id="snf-title">Advanced Communication</h2><p>24 governed File 17 enhancements. Provider-dependent capabilities remain unavailable until approved adapters are connected.</p></header><div id="snf-status" role="status">Loading capabilities…</div><div class="snf-grid"><form id="snf-lock-form" class="snf-card"><h3>Sensitive conversation lock</h3><label>Conversation ID<input name="conversation_id" type="number" min="1" required></label><label><input name="enabled" type="checkbox" checked> Require fresh step-up</label><button type="submit">Save lock policy</button></form><form id="snf-reminder-form" class="snf-card"><h3>Remind me later</h3><label>Conversation ID<input name="conversation_id" type="number" min="1" required></label><label>Reminder time<input name="remind_at" type="datetime-local" required></label><label>Label<input name="label" maxlength="191"></label><button type="submit">Create reminder</button></form><form id="snf-template-form" class="snf-card"><h3>Saved professional reply</h3><label>Title<input name="title" maxlength="120" required></label><label>Text<textarea name="body" maxlength="8000" required></textarea></label><button type="submit">Save template</button></form></div></section>';}
    public static function emit_contract(): void {do_action('sn_network_future_contract_registered',['owner'=>'file-17','schema_version'=>self::SCHEMA_VERSION,'feature_count'=>self::FEATURE_COUNT,'features'=>self::features(),'notification_owner'=>'file-19','global_search_owner'=>'file-26','private_message_search_owner'=>'file-17','ai_owner'=>'file-16','e2ee_claim'=>'provider-gated-audited-only']);}
    private static function create_record(string $f,int $owner,string $type,int $scope,array $data,string $client,?string $expires,string $state='active'): int|WP_Error {global $wpdb;$json=wp_json_encode($data,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);if(!is_string($json)||strlen($json)>self::MAX_PAYLOAD_BYTES)return self::error('sn_future_payload_invalid','Advanced communication data is too large.',413);$cipher=SN_Communication_Crypto::encrypt($json,'future-record|'.$f.'|'.$owner.'|'.$type.'|'.$scope);if(is_wp_error($cipher))return $cipher;$key=hash('sha256',$client);$ok=$wpdb->insert(self::records_table(),['feature_id'=>$f,'owner_id'=>$owner,'scope_type'=>$type,'scope_id'=>$scope,'state'=>$state,'payload_cipher'=>$cipher,'client_key'=>$key,'expires_at'=>$expires,'created_at'=>self::now(),'updated_at'=>self::now()]);if($ok===false){$id=(int)$wpdb->get_var($wpdb->prepare('SELECT id FROM '.self::records_table().' WHERE client_key=%s',$key));return $id?:self::db_error();}return (int)$wpdb->insert_id;}
    private static function upsert_record(string $f,int $owner,string $type,int $scope,array $data,string $client,?string $expires): int|WP_Error {global $wpdb;$row=$wpdb->get_row($wpdb->prepare("SELECT * FROM ".self::records_table()." WHERE feature_id=%s AND owner_id=%d AND scope_type=%s AND scope_id=%d AND state<>'deleted' ORDER BY id DESC LIMIT 1",$f,$owner,$type,$scope));if(!$row)return self::create_record($f,$owner,$type,$scope,$data,$client,$expires);$json=wp_json_encode($data,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);$cipher=SN_Communication_Crypto::encrypt((string)$json,'future-record|'.$f.'|'.$owner.'|'.$type.'|'.$scope);if(is_wp_error($cipher))return $cipher;$ok=$wpdb->update(self::records_table(),['payload_cipher'=>$cipher,'expires_at'=>$expires,'state'=>'active','updated_at'=>self::now(),'version'=>(int)$row->version+1],['id'=>(int)$row->id,'version'=>(int)$row->version]);return $ok===1?(int)$row->id:self::error('sn_future_record_conflict','Advanced communication state changed before update.',409);}
    private static function active_record(string $f,int $owner,string $type,int $scope): ?object {global $wpdb;$x=$wpdb->get_row($wpdb->prepare("SELECT * FROM ".self::records_table()." WHERE feature_id=%s AND owner_id=%d AND scope_type=%s AND scope_id=%d AND state='active' ORDER BY id DESC LIMIT 1",$f,$owner,$type,$scope));return is_object($x)?$x:null;}
    private static function decode(object $x): array|WP_Error {$plain=SN_Communication_Crypto::decrypt((string)$x->payload_cipher,'future-record|'.(string)$x->feature_id.'|'.(int)$x->owner_id.'|'.(string)$x->scope_type.'|'.(int)$x->scope_id);if(is_wp_error($plain))return $plain;$d=json_decode($plain,true);return is_array($d)?$d:self::error('sn_future_record_invalid','Advanced communication data is invalid.',500);}
    private static function owned(string $f,int $u): array {global $wpdb;$rows=$wpdb->get_results($wpdb->prepare("SELECT * FROM ".self::records_table()." WHERE feature_id=%s AND owner_id=%d AND state NOT IN ('deleted','erased') ORDER BY id DESC LIMIT 200",$f,$u));$out=[];foreach(is_array($rows)?$rows:[] as $x){$d=self::decode($x);$out[]=['id'=>(int)$x->id,'state'=>(string)$x->state,'scope_type'=>(string)$x->scope_type,'scope_id'=>(int)$x->scope_id,'expires_at'=>$x->expires_at?(string)$x->expires_at:null,'data'=>is_wp_error($d)?null:$d];}return $out;}
    private static function scope(string $f,string $type,int $scope): array {global $wpdb;$rows=$wpdb->get_results($wpdb->prepare("SELECT * FROM ".self::records_table()." WHERE feature_id=%s AND scope_type=%s AND scope_id=%d AND state='active' ORDER BY id ASC LIMIT 200",$f,$type,$scope));$out=[];foreach(is_array($rows)?$rows:[] as $x){$d=self::decode($x);if(!is_wp_error($d))$out[]=['id'=>(int)$x->id,'owner_id'=>(int)$x->owner_id,'data'=>$d];}return $out;}
    private static function append_key_log(int $u,string $dev,string $event,string $fp,string $prev): void {global $wpdb;$last=(string)$wpdb->get_var('SELECT entry_hash FROM '.self::key_log_table().' ORDER BY id DESC LIMIT 1');$at=self::now();$hash=hash('sha256',$last.'|'.$u.'|'.$dev.'|'.$event.'|'.$fp.'|'.$prev.'|'.$at);$wpdb->insert(self::key_log_table(),['user_id'=>$u,'device_id'=>$dev,'event'=>$event,'fingerprint'=>$fp,'previous_fingerprint'=>$prev,'entry_hash'=>$hash,'created_at'=>$at]);}
    private static function activate_space_member(int $space,int $u,string $role,int $by): bool|WP_Error {global $wpdb;$s=$wpdb->get_row($wpdb->prepare('SELECT id,conversation_id,state FROM '.SN_DB::table('spaces').' WHERE id=%d',$space));if(!$s||!in_array((string)$s->state,['active','restricted'],true)||SN_Policy::is_suspended($u))return self::error('sn_space_unavailable','Community/account is unavailable.',409);$at=self::now();$m=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.SN_DB::table('space_members').' WHERE space_id=%d AND user_id=%d',$space,$u));$data=['role'=>$role,'status'=>'active','approved_by'=>$by,'left_at'=>null,'updated_at'=>$at];$ok=$m?$wpdb->update(SN_DB::table('space_members'),$data+['version'=>(int)$m->version+1],['id'=>(int)$m->id]):$wpdb->insert(SN_DB::table('space_members'),['space_id'=>$space,'user_id'=>$u,'joined_at'=>$at,'created_at'=>$at]+$data);if($ok===false)return self::db_error();$c=(int)$s->conversation_id;if($c){$cm=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.SN_DB::table('members').' WHERE conversation_id=%d AND user_id=%d',$c,$u));$cd=['role'=>$role==='observer'?'member':$role,'left_at'=>null,'joined_at'=>$at];$ok=$cm?$wpdb->update(SN_DB::table('members'),$cd,['id'=>(int)$cm->id]):$wpdb->insert(SN_DB::table('members'),['conversation_id'=>$c,'user_id'=>$u]+$cd);if($ok===false)return self::db_error();}return true;}
    private static function expire_temp(object $x): void {global $wpdb;$d=self::decode($x);if(is_wp_error($d))return;$space=(int)$x->scope_id;$u=(int)($d['user_id']??$x->owner_id);$at=self::now();$s=$wpdb->get_row($wpdb->prepare('SELECT conversation_id FROM '.SN_DB::table('spaces').' WHERE id=%d',$space));$wpdb->update(SN_DB::table('space_members'),['status'=>'expired','left_at'=>$at,'updated_at'=>$at],['space_id'=>$space,'user_id'=>$u,'status'=>'active']);if($s&&(int)$s->conversation_id)$wpdb->update(SN_DB::table('members'),['left_at'=>$at],['conversation_id'=>(int)$s->conversation_id,'user_id'=>$u,'left_at'=>null]);$wpdb->update(self::records_table(),['state'=>'expired','updated_at'=>$at,'version'=>(int)$x->version+1],['id'=>(int)$x->id,'version'=>(int)$x->version]);}
    private static function selected_message_ids(WP_REST_Request $r,int $c): array|WP_Error {$ids=array_slice(array_values(array_unique(array_filter(array_map('absint',(array)$r->get_param('message_ids'))))),0,self::MAX_SELECTED_MESSAGES);if(!$ids)return self::error('sn_selected_messages_required','Select one or more messages.',400);foreach($ids as $id){$m=self::message_row($id);if(!$m||(int)$m->conversation_id!==$c||$m->deleted_at)return self::not_found();}return $ids;}
    private static function plain_messages(array $ids,int $c): array|WP_Error {$out=[];foreach($ids as $id){$m=self::message_row($id);if(!$m||(int)$m->conversation_id!==$c)return self::not_found();$p=SN_Message_Body::decrypt_row($m);if(is_wp_error($p))return $p;$out[]=['message_id'=>$id,'sender_id'=>(int)$m->sender_id,'body'=>$p,'created_at'=>(string)$m->created_at];}return $out;}
    private static function future_time(string $v,int $max): string|WP_Error {$ts=strtotime($v);return(!$ts||$ts<=time()||$ts>time()+$max)?self::error('sn_future_time_invalid','Choose a valid future time within the permitted window.',400):gmdate('Y-m-d H:i:s',$ts);} private static function client(WP_REST_Request $r,int $u,string $p): string {$x=strtolower(trim((string)$r->get_param('client_id')));if(!preg_match('/^[a-z0-9][a-z0-9._:-]{7,63}$/',$x))$x=wp_generate_uuid4();return $u.':'.$p.':'.$x;} private static function enum(string $v,array $a,string $d): string {$v=sanitize_key($v);return in_array($v,$a,true)?$v:$d;} private static function pretty_fp(string $x): string {return strtoupper(implode(':',str_split(substr($x,0,32),4)));} private static function same_site(string $url): bool {return strtolower((string)wp_parse_url($url,PHP_URL_HOST))===strtolower((string)wp_parse_url(home_url('/'),PHP_URL_HOST));}
    private static function looks_like_pii(string $v): bool {return(bool)(preg_match('/\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/i',$v)||preg_match('/(?:\+?\d[\s().-]*){8,}/',$v)||preg_match('/\b\d{5}-?\d{7}-?\d\b/',$v)||preg_match('/\b(?:name|address|phone|cnic|passport)\s*[:=-]/i',$v));} private static function looks_clinical_directive(string $v): bool {return(bool)preg_match('/\b(prescribe|prescription|dose|dosage|diagnose|diagnosis|take\s+\d|potency)\b/i',$v);} private static function bandwidth_bucket(int $x): string {return$x<300?'very-low':($x<1000?'low':($x<3000?'medium':'high'));}
    private static function conversation_member(int $c,int $u): bool {return$c>0&&$u>0&&SN_DB::is_member($c,$u);} private static function conversation_manager(int $c,int $u): bool {return in_array(SN_DB::member_role($c,$u),['owner','moderator'],true)||current_user_can('manage_options');} private static function message_row(int $id): ?object {global $wpdb;$x=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.SN_DB::table('messages').' WHERE id=%d',$id));return is_object($x)?$x:null;} private static function call_member(int $call,int $u): bool {global $wpdb;return(bool)$wpdb->get_var($wpdb->prepare("SELECT id FROM ".SN_DB::table('call_members')." WHERE call_id=%d AND user_id=%d AND status IN ('invited','joined') LIMIT 1",$call,$u));} private static function call_manager(int $call,int $u): bool {global $wpdb;$c=(int)$wpdb->get_var($wpdb->prepare('SELECT conversation_id FROM '.SN_DB::table('calls').' WHERE id=%d',$call));if(!$c)return false;$host=self::active_record('F17-FUT-20',0,'call',$call);if($host){$d=self::decode($host);if(!is_wp_error($d)&&(int)($d['host_id']??0)===$u)return true;}return self::conversation_manager($c,$u);} private static function space_manager(int $s,int $u): bool {global $wpdb;$role=(string)$wpdb->get_var($wpdb->prepare("SELECT role FROM ".SN_DB::table('space_members')." WHERE space_id=%d AND user_id=%d AND status='active' AND left_at IS NULL",$s,$u));return in_array($role,['owner','administrator','moderator'],true)||current_user_can('manage_options');} private static function space_has_permanent_member(int $s,int $u): bool {global $wpdb;$active=(bool)$wpdb->get_var($wpdb->prepare("SELECT id FROM ".SN_DB::table('space_members')." WHERE space_id=%d AND user_id=%d AND status='active' AND left_at IS NULL",$s,$u));if(!$active)return false;$temp=self::active_record('F17-FUT-13',$u,'space',$s);return !$temp;}
    private static function records_table(): string {global $wpdb;return$wpdb->prefix.'sn_future_records';} private static function device_keys_table(): string {global $wpdb;return$wpdb->prefix.'sn_future_device_keys';} private static function key_log_table(): string {global $wpdb;return$wpdb->prefix.'sn_future_key_log';} private static function versions_table(): string {global $wpdb;return$wpdb->prefix.'sn_future_message_versions';} private static function now(): string {return current_time('mysql',true);} private static function not_found(): WP_Error {return self::error('not_found','Requested communication object is unavailable.',404);} private static function db_error(): WP_Error {return self::error('database_error','Advanced communication change could not be stored safely.',500);} private static function error(string $c,string $m,int $s): WP_Error {return new WP_Error($c,$m,['status'=>$s]);}
